function* active<T extends { active: boolean }>(xs: Iterable<T>): Generator<T> {
  for (const x of xs) if (x.active) yield x;
}
function* take<T>(n: number, xs: Iterable<T>): Generator<T> {
  let i = 0;
  for (const x of xs) {
    if (i++ >= n) return;
    yield x;
  }
}

const firstEmails = [...take(3, active(people))].map(p => p.email);
